        if ((t * TILE_DIM + ty) < N && col < N) {
            b_tile[ty][tx] = b[(t * TILE_DIM + ty) * N + col];
        } else {
            b_tile[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Multiply tiles
        for (int k = 0; k < TILE_DIM; k += REG_TILE_SIZE) {
            #pragma unroll
